            )
            for category, (count, percentage) in cohort.get_cohort_trait_counts(
                cohort.cases.all(), "gender__display"
            ).items()
        ],
        neoplasticSites=[
            scm.CohortTraitCounts(
                category=category, counts=count, percentage=percentage
            )
            for category, (count, percentage) in cohort.get_cohort_trait_counts(
